    public static function key(string $source):string{return 'finance_export_'.substr(hash('sha256',$source),0,24);}
    public static function messages(string $locale):array
    {
        $english=explode('-',$locale,2)[0]==='en';$messages=[];
        foreach(self::ENGLISH as$source=>$translation)$messages[self::key($source)]=$english?$translation:$source;
        return $messages;
    }
    public static function text(string $source,array $messages,array $values=[]):string
    {
        if(str_starts_with($source,'Ausgangsgutschrift: '))return self::text('Ausgangsgutschrift:',$messages).' '.self::text(substr($source,strlen('Ausgangsgutschrift: ')),$messages);
        if($source!=='Gültiges aktives SKR42-Geldkonto für {account} auswählen.'&&preg_match('/\AGültiges aktives SKR42-Geldkonto für (.*) auswählen\.\z/sD',$source,$match))return self::text('Gültiges aktives SKR42-Geldkonto für {account} auswählen.',$messages,['account'=>$match[1]]);
        $text=$messages[self::key($source)]??FinanceTaxMessages::text(FinanceReceiptMessages::text($source,$messages),$messages);
        return $values?strtr($text,array_combine(array_map(static fn(string$key):string=>'{'.$key.'}',array_keys($values)),array_values($values))):$text;
    }
}
